const huntPageHtml = "<!doctype html>\n<html lang=\"de\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#02040a\">\n<title>ALO Kiosk City Hunt · 10K Special · Aarau</title>\n<style nonce=\"__HUNT_NONCE__\">\n:root{color-scheme:dark;--bg:#02040a;--panel:#07101f;--line:#202938;--text:#ffffff;--muted:#a0a7b6;--blue:#159cff;--red:#ff5a45}\n.heading-gap{margin-top:12px}.heading-zero{margin-top:0}*{box-sizing:border-box}html{scroll-behavior:smooth}\nbody{margin:0;background:var(--bg);color:var(--text);font:16px/1.55 system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}\na{color:inherit}button,input,select{font:inherit}\nbutton,a.button{min-height:48px;border:0;border-radius:12px;padding:13px 20px;font-weight:800;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;background:var(--blue);color:#ffffff}\nbutton.secondary,a.secondary{background:#101b2b;color:var(--text);border:1px solid var(--line)}\nbutton:disabled{opacity:.55;cursor:not-allowed}\n:focus-visible{outline:3px solid var(--blue);outline-offset:4px}\n.wrap{width:min(1080px,calc(100% - 36px));margin:auto}\nnav{display:flex;justify-content:space-between;align-items:center;padding:22px 0;gap:12px}\n.brand{text-decoration:none;font-size:24px;font-weight:950;letter-spacing:-1px}\n.brand span{color:var(--blue)}.tag{font-size:12px;letter-spacing:2px;font-weight:800;text-transform:uppercase}\nnav a:last-child{font-size:14px;color:var(--muted)}\n.hero{position:relative;padding:54px 0 48px;overflow:hidden}\n.hero:before{content:\"\";position:absolute;right:-140px;top:-110px;width:460px;height:460px;border:1px solid #159cff35;border-radius:50%;box-shadow:0 0 0 65px #159cff0b,0 0 0 130px #159cff06;pointer-events:none}\n.pill{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:99px;padding:7px 12px;font-size:13px;background:#07101f}\n.dot{width:7px;height:7px;background:var(--blue);border-radius:50%}\nh1{font-size:clamp(48px,9vw,98px);line-height:.98;letter-spacing:-.065em;margin:28px 0 22px;max-width:780px}\nh1 span{color:var(--blue)}h2{font-size:clamp(25px,4vw,38px);line-height:1.15;letter-spacing:-1px;margin:0 0 15px}\nh3{font-size:22px;line-height:1.2;margin:16px 0 10px}\n.lead{font-size:19px;max-width:590px;color:var(--muted)}\n.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}\n.meta{display:flex;gap:20px;flex-wrap:wrap;color:var(--muted);font-size:14px;margin-top:25px}\n.prize{display:grid;grid-template-columns:1.25fr 1fr;gap:25px;align-items:center;background:var(--blue);color:#ffffff;border-radius:20px;padding:30px;margin:15px 0 56px}\n.prize strong{display:block;font-size:clamp(60px,10vw,100px);line-height:1;letter-spacing:-6px}\n.prize p{margin:12px 0 0}.breakdown{font-weight:750;font-size:17px}\nsection{margin-bottom:56px;scroll-margin-top:20px}\n.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:24px}\n.card p,.muted{color:var(--muted)}.card p{margin:0}\n.number{color:var(--blue);font-size:12px;font-weight:800;letter-spacing:2px}\n.reward{display:inline-block;margin-top:20px;padding:6px 10px;background:#082647;border-radius:8px;color:var(--blue);font-weight:800;font-size:14px}\n.split{display:grid;grid-template-columns:1fr 1fr;gap:28px}\n.notice{border-left:3px solid var(--blue);background:#091a2e;padding:15px 18px;border-radius:0 10px 10px 0;margin:20px 0}\nfieldset{padding:0;border:0;margin:0;min-width:0}\nlabel{display:block;margin:14px 0 6px;font-weight:650;font-size:14px}\ninput,select{width:100%;min-height:48px;background:#050b14;border:1px solid #34465e;border-radius:10px;color:var(--text);padding:11px 13px}\n.check{display:flex;gap:10px;font-weight:400;align-items:flex-start}\n.check input{width:18px;min-height:18px;margin-top:4px;flex:none}\nfieldset:disabled{opacity:.65}.full{width:100%;margin-top:18px}\n.steps{padding-left:22px;color:var(--muted)}.steps li{padding:8px 0}\ndetails{border-top:1px solid var(--line);padding:17px 0}summary{cursor:pointer;font-weight:750}details p{color:var(--muted)}\n.status{white-space:pre-line}.status:empty{display:none}\n.passname{font-size:32px;letter-spacing:-1px;font-weight:850}\ndl{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:20px 0}\ndt{color:var(--muted)}dd{margin:0;text-align:right}\nfooter{border-top:1px solid var(--line);padding:28px 0 40px;color:var(--muted);font-size:13px}\n[hidden]{display:none!important}\n@media(max-width:700px){.hero{padding-top:30px}.hero:before{opacity:.5}.prize,.split,.grid{grid-template-columns:1fr}.prize{padding:25px;gap:20px}.grid{gap:12px}.card{padding:21px}.prize strong{letter-spacing:-4px}.lead{font-size:17px}section{margin-bottom:38px}}\n@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n\n/* ALO-Shop-Farben und mobile Eventbedienung */\nbody{font-family:Arial,Helvetica,sans-serif}\n.wrap{width:min(1040px,calc(100% - 32px))}\nnav{border-bottom:1px solid var(--line);padding:16px 0}\n.brand{display:flex;align-items:center;gap:12px;min-width:0}\n.brand-wordmark{color:#fff!important;font-size:23px;font-weight:900}\n.brand .tag{color:#72caff;font-size:11px;letter-spacing:1.5px}\n.brand-logo{display:block;width:140px;height:auto;max-height:64px;object-fit:contain}\n.hero{padding:42px 0 34px}\nh1{font-size:clamp(42px,8vw,80px);line-height:1.04;letter-spacing:-.045em}\nh1 span{color:#19c8ff}\nbutton,a.button{border-radius:9px}\n.card{border-radius:12px}\n.prize{border-radius:12px;background:#082647;border:1px solid #159cff66;padding:26px;margin-bottom:40px}\n.prize strong{color:#fff;font-size:clamp(52px,9vw,84px);letter-spacing:-3px}\n.prize .tag{color:#72caff}\n.prize p{color:#c5d9ef}\n.breakdown{font-size:16px;line-height:1.8}\n.reward{color:#72caff}\n.notice{line-height:1.55}\n#attendance-panel p{margin-top:8px}\n#withdrawal-panel p{margin-top:10px}\n#attendance-date{font-weight:700;color:#fff}\n#pass-content .actions{margin-top:14px}\n@media(max-width:700px){\n  .wrap{width:calc(100% - 28px)}\n  nav{gap:8px}\n  .brand{gap:8px}\n  .brand-logo{width:110px;max-height:52px}\n  .brand-wordmark{font-size:20px}\n  .brand .tag{font-size:9px;letter-spacing:1px}\n  nav a:last-child{font-size:12px;white-space:nowrap}\n  h1{font-size:clamp(40px,11vw,66px)}\n  .hero{padding:30px 0}\n  .hero:before{opacity:.25}\n  .lead{line-height:1.6}\n  .prize{padding:22px;gap:14px}\n  .card{padding:20px}\n  .passname{font-size:27px;overflow-wrap:anywhere}\n  #pass-content .actions{flex-direction:column}\n  #pass-content .actions button{width:100%}\n  dl{grid-template-columns:auto minmax(0,1fr)}\n  dd{overflow-wrap:anywhere}\n}\n@media(max-width:360px){\n  .brand{flex-direction:column;align-items:flex-start;gap:2px}\n}\n\n\n/* City Hunt: kompakte Missionen und klare Belohnungen */\n.event-timing{font-size:14px;margin:14px 0 0}\n.hunt-hud{display:grid;grid-template-columns:.8fr 1.2fr 1fr;gap:12px;margin-top:26px}\n.hunt-hud>div{display:flex;flex-direction:column;gap:5px;padding:17px;background:#07101f;border:1px solid #202938;border-top:2px solid #159cff;border-radius:10px}\n.hud-label{color:#72caff;font-size:10px;font-weight:800;letter-spacing:1.3px}\n.hunt-hud strong{font-size:19px;line-height:1.25}\n.hunt-hud>div>span:last-child{font-size:12px;color:var(--muted)}\n.prize{margin-top:0}\n.breakdown>div{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:11px 0;border-bottom:1px solid #ffffff20}\n.breakdown>div:last-child{border:0}\n.breakdown>div>span{font-size:13px;color:#c5d9ef;font-weight:400}\n.prize .breakdown strong{font-size:21px;letter-spacing:-.5px;white-space:nowrap}\n.game-guide{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}\n.game-guide>div{border-left:2px solid #159cff;padding:3px 0 3px 15px}\n.guide-index{display:block;font-size:11px;letter-spacing:2px;color:#72caff;font-weight:800;margin-bottom:7px}\n.game-guide strong{font-size:16px}\n.game-guide p{font-size:14px;color:var(--muted);margin:7px 0 0}\n.family-note p{margin-top:8px}\n@media(max-width:700px){\n  .hunt-hud{grid-template-columns:1fr 1fr;gap:10px}\n  .hunt-hud>div:nth-child(2){grid-column:1/-1;grid-row:2}\n  .hunt-hud strong{font-size:18px}\n  .hunt-hud>div{padding:14px}\n  .game-guide{grid-template-columns:1fr;gap:18px}\n  .breakdown>div{padding:10px 0}\n  .prize .breakdown strong{font-size:20px}\n  .hero>.actions{display:grid;grid-template-columns:1fr}\n  .hero>.actions a{width:100%}\n}\n\n\n.mission-progress{margin:22px 0 14px}\n.mission-progress strong{display:block;font-size:14px;margin-bottom:8px}\n.mission-progress progress{width:100%;height:12px;accent-color:#159cff}\n.mission-digits{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0 24px}\n.digit-tile{display:grid;place-items:center;width:48px;height:54px;border:1px solid #34465e;border-radius:8px;background:#050b14;color:#718090;font-size:24px;font-weight:800}\n.digit-tile.earned{color:#fff;border-color:#159cff;background:#082647}\n.mission-task{white-space:pre-line;line-height:1.65}\n#mission-area{font-size:14px;overflow-wrap:anywhere}\n#mission-answer-form{margin:20px 0}\n#mission-discover{width:100%}\n.mission-hints{margin-top:24px}\n#mission-final p{margin-top:8px}\n@media(max-width:700px){\n  #mission .actions button{width:100%}\n  .digit-tile{width:42px;height:48px}\n}\n\n\n/* ALO: ruhiger Aufbau, echte Marke, klare Preise */\n.hero:before{display:none!important}\n.hero{overflow:visible;padding:36px 0 28px}\nh1{font-size:clamp(42px,7.5vw,76px);line-height:1.04;letter-spacing:-.045em;max-width:820px;margin:22px 0 18px}\n.hero .lead{max-width:650px;font-size:18px;line-height:1.6}\n.pill{border-radius:6px;background:#091a2e;border-color:#203c5a;color:#b9ddff;font-size:11px;font-weight:800;letter-spacing:1px}\n.hero .actions{margin-top:22px}\n.meta{gap:10px 18px;margin-top:20px}\n.meta span{font-size:13px}\n.event-timing{margin-top:10px;color:#a0a7b6}\n.hunt-hud{gap:0;border:1px solid #202938;border-radius:10px;overflow:hidden;background:#07101f;margin-top:24px}\n.hunt-hud>div{border:0;border-right:1px solid #202938;border-radius:0;background:transparent;padding:16px 18px}\n.hunt-hud>div:last-child{border-right:0}\n.hud-label{letter-spacing:1px}\n.hunt-hud strong{font-size:17px}\n.prize{background:#07101f;border:1px solid #203c5a;position:relative;margin-bottom:36px}\n.prize:before{content:\"\";position:absolute;left:0;top:20px;bottom:20px;width:3px;background:#159cff;border-radius:2px}\n.prize strong{font-size:clamp(54px,8vw,78px);letter-spacing:-3px}\n.prize p{font-size:14px;max-width:340px;color:#a0a7b6}\n.breakdown>div>span{font-size:14px;color:#d8e4f1;font-weight:600}\n.prize .breakdown strong{font-size:23px;color:#72caff}\n.grid .card{padding:22px;border-top:2px solid #159cff;background:#07101f}\n.grid .card h3{font-size:23px;letter-spacing:-.6px}\n.grid .card p{font-size:15px;line-height:1.65}\n.reward{border-radius:6px;border:1px solid #203c5a;background:#091a2e}\n.number{letter-spacing:1px;font-size:11px}\nh2{letter-spacing:-.8px}\nfooter{line-height:1.8}\n@media(max-width:700px){\n  .hero{padding:26px 0}\n  h1{font-size:clamp(40px,10.5vw,66px)}\n  .hero .lead{font-size:16px}\n  .hero>.actions{grid-template-columns:1fr 1fr;gap:10px}\n  .hero>.actions a{padding:12px 10px;font-size:14px}\n  .hunt-hud{grid-template-columns:1fr 1fr}\n  .hunt-hud>div{padding:14px}\n  .hunt-hud>div:nth-child(1){border-right:1px solid #202938}\n  .hunt-hud>div:nth-child(3){border-right:0}\n  .hunt-hud>div:nth-child(2){border-top:1px solid #202938;border-right:0}\n  .hunt-hud strong{font-size:16px}\n  .prize{padding:22px}\n  .prize:before{top:18px;bottom:18px}\n  .prize .breakdown strong{font-size:22px}\n  .grid .card{padding:20px}\n}\n\n\n/* Auf einen Blick: Anlass, Event, Preise und Teilnahme */\nnav{padding:12px 0}\n.hero{padding:26px 0 20px}\n.hero h1{font-size:clamp(42px,6.5vw,68px);margin:18px 0 14px;line-height:1.02}\n.hero .lead{font-size:17px;max-width:620px;margin:0}\n.hero .lead strong{color:#fff}\n.hero .actions{margin-top:20px}\n.hero .meta{margin-top:16px}\n.event-timing{margin:8px 0 0;font-size:13px}\n.prize{padding:22px 26px;margin-bottom:32px;gap:20px}\n.prize>div:first-child>strong{font-size:clamp(48px,7vw,68px)}\n.prize p{margin-top:8px}\n.breakdown>div{padding:8px 0}\n#spiel .heading-gap{margin-top:8px}\n@media(min-width:850px){\n  .hero{display:grid;grid-template-columns:1fr auto;column-gap:24px}\n  .hero>.pill,.hero>h1,.hero>.lead{grid-column:1}\n  .hero>.actions{grid-column:2;grid-row:2/4;align-self:center;flex-direction:column;margin:0;min-width:170px}\n  .hero>.meta,.hero>.event-timing{grid-column:1/-1}\n}\n@media(max-width:700px){\n  .hero{padding:22px 0 18px}\n  .hero h1{font-size:46px;margin:15px 0 12px}\n  .hero .lead{font-size:15px;line-height:1.55}\n  .pill{font-size:10px;letter-spacing:.5px;padding:6px 9px}\n  .hero .actions{margin-top:16px}\n  .hero .meta{gap:6px 12px;margin-top:14px}\n  .meta span,.event-timing{font-size:12px}\n  .prize{padding:18px 20px;gap:12px;margin-bottom:28px}\n  .prize>div:first-child>strong{font-size:52px}\n  .prize .tag{font-size:10px;letter-spacing:1px}\n  .prize p{font-size:13px}\n  .breakdown>div{padding:7px 0}\n  .breakdown>div>span{font-size:13px}\n  .prize .breakdown strong{font-size:20px}\n}\n\n\n/* ALO Anmeldung: kompakt und direkt */\n#anmeldung{gap:22px;align-items:start}\n#anmeldung h2{font-size:clamp(30px,4vw,42px);margin-bottom:12px}\n#anmeldung>.card{background:#07101f;border-color:#203c5a}\n#anmeldung .steps{padding-left:20px;margin:14px 0;font-size:15px}\n#anmeldung .steps li{padding:5px 0}\n#anmeldung .notice{font-size:14px;margin:16px 0 0}\n#registration-note{font-size:14px}\n@media(max-width:700px){\n  #anmeldung{gap:18px}\n  #anmeldung h2{font-size:32px}\n  #anmeldung>.card{padding:20px}\n}\n\n\n#mission-map{display:block;width:100%;height:auto;background:#dce5ef;\nborder:1px solid var(--line);border-radius:12px;margin-top:14px}\n.hunt-map-credit{font-size:12px;margin:6px 0 12px}\n.hunt-map-credit a{color:var(--blue)}\n#mission-map-status{font-size:14px}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n<nav aria-label=\"Hauptnavigation\">\n<a class=\"brand\" href=\"#start\"><img class=\"brand-logo\" src=\"data:image/png;base64,\" alt=\"ALO Kiosk\" width=\"140\"><small class=\"tag\">CITY HUNT</small></a>\n<a href=\"#spielerpass\">Mein Spielerpass ↗</a>\n</nav>\n\n<main>\n<header class=\"hero\" id=\"start\">\n<div class=\"pill\"><span class=\"dot\"></span>10’000 TIKTOK-FOLLOWER · DANKE EUCH!</div>\n<h1>ALO Kiosk<br><span>City Hunt.</span></h1>\n<p class=\"lead\">Unser 10K Special: eine Schnitzeljagd durch Aarau mit <strong>CHF 500 Geldpreisen</strong> und Snack-Belohnungen. Finde Codes, löse Rätsel und spiele allein oder mit deinen Leuten.</p>\n<div class=\"actions\">\n<a class=\"button\" href=\"#anmeldung\">Mitmachen</a>\n<a class=\"button secondary\" href=\"#spiel\">So läuft’s</a>\n</div>\n<div class=\"meta\"><span>Gratis teilnehmen</span><span>Keine App nötig</span><span>Allein oder gemeinsam</span></div>\n<p class=\"muted event-timing\">Termin folgt · Start und Finale am ALO Kiosk Aarau</p>\n\n</header>\n\n<div class=\"prize\" aria-label=\"Geldpreise: insgesamt 500 Schweizer Franken\">\n<div><span class=\"tag\">500 FRANKEN · 14 GELDPREISE</span><strong>CHF 500</strong><p>Dazu Snacks, Drinks und Sticker.</p></div>\n<div class=\"breakdown\">\n<div><span>1× Hauptgewinn</span><strong>CHF 250</strong></div>\n<div><span>3× Geldschätze</span><strong>CHF 50</strong></div>\n<div><span>10× Geldschätze</span><strong>CHF 10</strong></div>\n</div>\n</div>\n\n<section id=\"spiel\">\n<span class=\"number\">DAS ALO 10K SPECIAL</span>\n<h2 class=\"heading-gap\">Was suchst du zuerst?</h2>\n<div class=\"grid\">\n<article class=\"card\"><span class=\"number\">HAUPTQUEST</span><h3>Knack den Finalcode.</h3><p>Entdecke eine Station, löse ihre Aufgabe und sichere dir eine Ziffer. Schritt für Schritt setzt du den Finalcode zusammen. Der Hauptgewinn wird einmal vergeben.</p><span class=\"reward\">CHF 250</span></article>\n<article class=\"card\"><span class=\"number\">GELDSCHÄTZE</span><h3>Finde deinen Geldschatz.</h3><p>Folge dem Suchgebiet und den freigegebenen Tipps. Ein Geldfund gehört dem Spieler, der seinen gültigen Fundcode zuerst erfolgreich beansprucht.</p><span class=\"reward\">CHF 50 oder CHF 10</span></article>\n<article class=\"card\"><span class=\"number\">SNACKJAGD</span><h3>Hol dir was Leckeres.</h3><p>Entdecke einen Belohnungs-QR und sichere dir einen verfügbaren Gutschein. Dein Fund erscheint im Spielerpass – zur Abholung am Kiosk.</p><span class=\"reward\">Snacks · Sticker · Produkte</span></article>\n</div>\n<div class=\"game-guide\">\n<div><span class=\"guide-index\">01</span><strong>Suchgebiet entdecken</strong><p>Dein Handy zeigt dir, wo du ungefähr suchen sollst.</p></div>\n<div><span class=\"guide-index\">02</span><strong>Checkpoint finden</strong><p>QR scannen, Aufgabe lösen und deinen Fortschritt speichern.</p></div>\n<div><span class=\"guide-index\">03</span><strong>Finale am Kiosk</strong><p>Mit deinem gültigen Gewinnnachweis zurück zum Startpunkt.</p></div>\n</div>\n<div class=\"notice family-note\"><strong>Gemeinsam macht’s mehr Spass.</strong><p>Kommt mit Freunden, als Paar oder als Familie. Jeder spielt mit seinem eigenen Pass. Für Kinder unter 14 ist eine erwachsene Begleitung vorgesehen. Die Website führt euch Schritt für Schritt durch das Spiel.</p></div>\n<p class=\"muted\">Route, Spielzeiten, Teilnahmebedingungen und Abholregeln stehen vor der Platzbestätigung fest.</p>\n</section>\n\n<section class=\"split\" id=\"anmeldung\">\n<div>\n<span class=\"number\">MITMACHEN</span>\n<h2 class=\"heading-gap\">Bisch debii?</h2>\n<p class=\"muted\">E-Mail eintragen, Link öffnen und mitmachen. Wenn der Termin steht, bestätigst du deinen Platz. Deine gelösten Stationen bleiben gespeichert.</p>\n<ol class=\"steps\">\n<li>Spielername, E-Mail und Altersgruppe eintragen.</li>\n<li>Den Link in deiner E-Mail öffnen.</li>\n<li>Unter 18? Deine Eltern bestätigen die Teilnahme.</li>\n<li>Termin prüfen und deinen Platz bestätigen.</li>\n</ol>\n<div class=\"notice\">Unter 14 kommst du mit einer erwachsenen Begleitung. Filmen oder Posten musst du nicht.</div>\n</div>\n<div class=\"card\">\n<h3 class=\"heading-zero\">Anmelden</h3>\n<p id=\"registration-note\" role=\"status\">Die Anmeldung öffnet bald. Den Start kündigen wir bei ALO an.</p>\n<form id=\"registration-form\">\n<fieldset disabled>\n<label for=\"alias\">Spielername</label>\n<input id=\"alias\" name=\"alias\" minlength=\"3\" maxlength=\"24\" pattern=\"[A-Za-z0-9_-]{3,24}\" autocomplete=\"nickname\" placeholder=\"DeinSpielername\" required>\n<label for=\"email\">E-Mail</label>\n<input id=\"email\" name=\"contactEmail\" type=\"email\" maxlength=\"254\" autocomplete=\"email\" placeholder=\"du@beispiel.ch\" required>\n<label for=\"age\">Altersgruppe</label>\n<select id=\"age\" name=\"ageGroup\" required><option value=\"\">Bitte auswählen</option><option value=\"UNDER_14\">Unter 14</option><option value=\"14_17\">14–17</option><option value=\"ADULT\">Ab 18</option></select>\n<label class=\"check\"><input type=\"checkbox\" required><span>Ich akzeptiere die Teilnahmebedingungen, sobald sie hier veröffentlicht sind.</span></label>\n<label class=\"check\"><input type=\"checkbox\" required><span>Ich habe die Datenschutzhinweise gelesen, sobald sie hier veröffentlicht sind.</span></label>\n<button class=\"full\" type=\"submit\">Warteliste öffnet bald</button>\n</fieldset>\n</form>\n</div>\n</section>\n\n<section id=\"spielerpass\" class=\"card\">\n<span class=\"number\">MEIN SPIELERPASS</span>\n<h2 class=\"heading-gap\">Schon angemeldet?</h2>\n<p class=\"muted\" id=\"pass-intro\">Öffne deinen Zugang aus der E-Mail. Hier findest du deinen Platz, deine Stationen und später deine Gewinne. Dein Fortschritt bleibt gespeichert.</p>\n<div id=\"link-panel\" hidden>\n<div class=\"notice\">Dein Link ist bereit. Bestätige hier, dass du deinen Spielerpass öffnen möchtest.</div>\n<button id=\"consume-link\" type=\"button\">Spielerpass öffnen</button>\n</div>\n<div id=\"pass-content\" hidden>\n<div class=\"passname\" id=\"pass-alias\"></div>\n<p id=\"pass-message\" class=\"notice\"></p>\n<dl><dt>Phase</dt><dd id=\"pass-phase\"></dd><dt>Elternfreigabe</dt><dd id=\"pass-guardian\"></dd><dt>Unterlagen</dt><dd id=\"pass-docs\"></dd></dl>\n<div class=\"notice\" id=\"attendance-panel\">\n<strong id=\"attendance-title\">Deine Teilnahme</strong>\n<p id=\"attendance-detail\"></p>\n<p id=\"attendance-date\"></p>\n<p>Treffpunkt und Finale: ALO Kiosk, Zwischen den Toren 14, Aarau.</p>\n</div>\n<div class=\"actions\">\n<button id=\"confirm-attendance\" type=\"button\" hidden>Ich bin dabei – Platz bestätigen</button>\n<button class=\"secondary\" id=\"show-withdrawal\" type=\"button\" hidden>Teilnahme absagen</button>\n</div>\n<div id=\"withdrawal-panel\" class=\"notice\" hidden>\n<strong>Deinen Eventplatz freigeben?</strong>\n<p>Du kannst danach nicht mehr mitspielen. Dein Spielerpass und Fortschritt bleiben gespeichert. Eine erneute Zusage ist nur bei offener Anmeldung und freien Plätzen möglich.</p>\n<div class=\"actions\">\n<button class=\"secondary\" id=\"cancel-withdrawal\" type=\"button\">Platz behalten</button>\n<button id=\"confirm-withdrawal\" type=\"button\">Ja, Teilnahme absagen</button>\n</div>\n</div>\n<div class=\"actions\">\n<button class=\"secondary\" id=\"logout\" type=\"button\">Aus Spielerpass ausloggen</button>\n</div>\n</div>\n<p id=\"pass-status\" class=\"status muted\" role=\"status\" aria-live=\"polite\"></p>\n</section>\n\n\n<section id=\"mission\" class=\"card\" hidden>\n<span class=\"number\">DEINE HAUPTQUEST</span>\n<h2 class=\"heading-gap\" id=\"mission-title\">Deine nächste Station</h2>\n<p class=\"muted\" id=\"mission-introduction\"></p>\n<div class=\"mission-progress\">\n<strong id=\"mission-progress-label\">Fortschritt wird geladen</strong>\n<progress id=\"mission-progress\" value=\"0\" max=\"1\" aria-label=\"Gelöste Stationen\"></progress>\n</div>\n<div class=\"mission-digits\" id=\"mission-digits\" aria-label=\"Gesammelte Ziffern\"></div>\n<div id=\"mission-station\" hidden>\n<span class=\"number\" id=\"mission-position\"></span>\n<h3 id=\"mission-station-title\"></h3>\n<p class=\"mission-task\" id=\"mission-task\"></p>\n\n<div id=\"mission-map-panel\" hidden>\n  <svg id=\"mission-map\" viewBox=\"0 0 512 320\"\n       role=\"img\" aria-label=\"Karte des aktuellen Suchbereichs\"></svg>\n  <p class=\"hunt-map-credit\">© <a href=\"https://www.openstreetmap.org/copyright\"\n     target=\"_blank\" rel=\"noopener noreferrer\">OpenStreetMap</a> Mitwirkende</p>\n  <button id=\"mission-location\" type=\"button\" class=\"secondary\">Meinen Standort anzeigen</button>\n  <p id=\"mission-map-status\" class=\"muted\" role=\"status\" aria-live=\"polite\"></p>\n  <p class=\"muted\">Der blaue Kreis zeigt dein Suchgebiet, nicht den genauen Lösungsort. Standortanzeige ist freiwillig.</p>\n</div>\n\n<div class=\"notice\" id=\"mission-area\" hidden></div>\n<p class=\"muted\" id=\"mission-next-area\" hidden></p>\n<p class=\"muted\" id=\"mission-discovery\"></p>\n<button id=\"mission-discover\" type=\"button\" hidden>Gefundenen Checkpoint bestätigen</button>\n<form id=\"mission-answer-form\" hidden>\n<label for=\"mission-answer\">Was hast du herausgefunden?</label>\n<input id=\"mission-answer\" maxlength=\"200\" autocomplete=\"off\"\n       placeholder=\"Antwort eingeben\" aria-describedby=\"mission-answer-hint\" required>\n<p class=\"muted\" id=\"mission-answer-hint\" hidden></p>\n<button id=\"mission-submit\" type=\"submit\" class=\"full\">Antwort prüfen</button>\n</form>\n<div class=\"mission-hints\" id=\"mission-hints\" hidden>\n<h3>Deine Tipps</h3>\n<div id=\"mission-hint-list\"></div>\n<p class=\"muted\" id=\"mission-next-hint\"></p>\n</div>\n</div>\n<div id=\"mission-final\" class=\"notice\" hidden>\n<strong>Alle Stationen gelöst.</strong>\n<p>Du hast alle Ziffern gesammelt. Die Finalcode- und Gewinnprüfung wird noch ergänzt. Dieser Bildschirm ist kein Gewinnnachweis.</p>\n</div>\n<div class=\"actions\">\n<button id=\"mission-refresh\" class=\"secondary\" type=\"button\">Mission aktualisieren</button>\n</div>\n<p id=\"mission-status\" class=\"status muted\" role=\"status\" aria-live=\"polite\"></p>\n</section>\n\n<section class=\"split\">\n<div>\n<span class=\"number\">10K SPECIAL</span>\n<h2 class=\"heading-gap\">Zeig uns deine Hunt.</h2>\n<p class=\"muted\">Ein guter Fund, eure Reaktion oder der Moment am Kiosk: Wenn du Lust hast, halte eure Schatzsuche fest. Wie du Clips für unseren Rückblick einreichen kannst, geben wir vor dem Event bekannt. Mitspielen geht natürlich auch ohne Kamera.</p>\n</div>\n<div>\n<h3>Gut zu wissen</h3>\n<details><summary>Wann findet die Schnitzeljagd statt?</summary><p>Der Termin folgt. Aktuell ist auch die Warteliste noch geschlossen.</p></details>\n<details><summary>Muss ich TikTok haben?</summary><p>Nein. Das eigentliche Spiel läuft auf dieser Website. Ein Folgen-Link zu ALO wird ergänzt.</p></details>\n<details><summary>Wie funktionieren die Hinweise?</summary><p>Geplant sind Suchgebiete, Texträtsel und zeitgesteuerte Bildhinweise. Genaue Fundcodes bleiben geheim. Die endgültigen Spielregeln folgen.</p></details>\n<details><summary>Wo hole ich einen Gewinn ab?</summary><p>Die Abholung ist im ALO Kiosk, Zwischen den Toren 14, 5000 Aarau geplant. Dein gültiger Gewinnnachweis und die Abholfrist stehen später im Spielerpass.</p></details>\n<details id=\"damaged-checkpoint-faq\">\n<summary>Was mache ich, wenn ein QR-Code beschädigt ist?</summary>\n<p>Notiere die Stationsnummer und melde dich beim Hunt-Team am ALO Kiosk. Ein Foto hilft uns bei der Prüfung. Wir ersetzen beschädigte Codes. Falls nötig, prüft das Team einen Ersatzweg für deine Rätselstation, damit die Suche weitergehen kann.</p>\n<p>Dein bisheriger Fortschritt bleibt gespeichert. Ersatzcodes ändern weder die Anzahl der Gewinne noch die Regel, dass ein Geldfund nur einmal vergeben wird.</p>\n</details>\n<details><summary>Was passiert bei technischen Problemen?</summary><p>Vor dem Start veröffentlichen wir eine Anlaufstelle und den Ablauf bei Verbindungsproblemen. Suche nur auf erlaubten Wegen; betrete keine privaten oder gefährlichen Bereiche.</p></details>\n</div>\n</section>\n</main>\n<footer>ALO Kiosk City Hunt · Das 10K Special<br>Start und Finale: Zwischen den Toren 14, 5000 Aarau.<br>Termin folgt. Anmeldung noch geschlossen. Teilnahmebedingungen, Datenschutz und Kontakt folgen vor der Öffnung.</footer>\n</div>\n\n<script nonce=\"__HUNT_NONCE__\">\n(function(){\n\"use strict\";\nvar api=\"/api/city-hunt\";\nvar currentPass=null;\nvar attendanceBusy=false;\nvar confirmAttendance=document.getElementById(\"confirm-attendance\");\nvar showWithdrawal=document.getElementById(\"show-withdrawal\");\nvar confirmWithdrawal=document.getElementById(\"confirm-withdrawal\");\nvar cancelWithdrawal=document.getElementById(\"cancel-withdrawal\");\nvar withdrawalPanel=document.getElementById(\"withdrawal-panel\");\n\nfunction setAttendanceBusy(value){\n  attendanceBusy=value;\n  [confirmAttendance,showWithdrawal,confirmWithdrawal,cancelWithdrawal]\n    .forEach(function(element){element.disabled=value;});\n}\n\nfunction formatHuntDate(value){\n  if(!value) return \"\";\n  var date=new Date(value);\n  if(!Number.isFinite(date.getTime())) return \"\";\n  return new Intl.DateTimeFormat(\"de-CH\",{\n    timeZone:\"Europe/Zurich\",\n    weekday:\"short\",day:\"2-digit\",month:\"2-digit\",year:\"numeric\",\n    hour:\"2-digit\",minute:\"2-digit\"\n  }).format(date);\n}\n\nfunction renderAttendance(data){\n  var participation=data.participation||{};\n  var labels={\n    WAITING_DATE:\"Termin folgt\",\n    NOT_CONFIRMED:\"Dein Platz ist noch nicht bestätigt\",\n    CONFIRMED:\"Du bist dabei\",\n    WITHDRAWN:\"Teilnahme abgesagt\",\n    NEEDS_RECONFIRMATION:\"Bitte erneut bestätigen\"\n  };\n  document.getElementById(\"attendance-title\").textContent=\n    labels[participation.status]||\"Deine Teilnahme\";\n  document.getElementById(\"attendance-detail\").textContent=\n    participation.confirmed\n      ?\"Dein Platz ist für den angezeigten Termin bestätigt.\"\n      :participation.status===\"WITHDRAWN\"\n        ?\"Dein Eventplatz wurde freigegeben.\"\n        :participation.status===\"NEEDS_RECONFIRMATION\"\n          ?\"Termin oder Unterlagen wurden geändert. Deine bisherige Zusage gilt nicht mehr.\"\n          :participation.status===\"WAITING_DATE\"\n            ?\"Du bist vorgemerkt. Sobald der Termin feststeht, folgt die Platzbestätigung.\"\n            :\"Bestätige den angezeigten Termin, sobald deine Anmeldung vollständig und die Platzvergabe geöffnet ist.\";\n  var start=formatHuntDate(data.event.startsAt);\n  var end=formatHuntDate(data.event.endsAt);\n  document.getElementById(\"attendance-date\").textContent=\n    start&&end?\"Start: \"+start+\" · Ende: \"+end+\" Uhr\":\"Der Eventtermin wird noch bekannt gegeben.\";\n  confirmAttendance.hidden=participation.canConfirm!==true;\n  showWithdrawal.hidden=participation.canWithdraw!==true;\n  withdrawalPanel.hidden=true;\n}\nvar status=document.getElementById(\"pass-status\");\nvar button=document.getElementById(\"consume-link\");\nvar fragment=new URLSearchParams(location.hash.slice(1));\nvar kind=fragment.get(\"action\");\nvar code=fragment.get(\"code\");\nvar linkReady=(kind===\"verify\"||kind===\"login\")&&/^[A-Za-z0-9_-]{43}$/.test(code||\"\");\nif(linkReady){\n  history.replaceState(null,\"\",location.pathname+location.search+\"#spielerpass\");\n  document.getElementById(\"link-panel\").hidden=false;\n}\n\nvar errors={\nHUNT_GAME_NOT_READY:\"Das Spiel ist noch nicht freigegeben.\",\nPARTICIPATION_NOT_CONFIRMED:\"Bitte bestätige zuerst deine Teilnahme für diesen Termin.\",\nQUEST_NOT_AVAILABLE:\"Diese Mission ist momentan nicht geöffnet.\",\nINVALID_QUEST:\"Dieser Missionslink ist ungültig.\",\nINVALID_STATION:\"Dieser Stationslink ist ungültig.\",\nINVALID_STATION_CODE:\"Dieser QR-Code passt nicht zu deiner aktuellen Station.\",\nINVALID_STATION_ACTION:\"Die Stationsaktion konnte nicht verarbeitet werden.\",\nINVALID_ANSWER:\"Bitte gib eine gültige Antwort mit höchstens 200 Zeichen ein.\",\nSTATION_NOT_CURRENT:\"Diese Station ist aktuell nicht an der Reihe. Aktualisiere deine Mission.\",\nSTATION_NOT_DISCOVERED:\"Scanne zuerst den QR-Code dieser Station.\",\nHUNT_WEB_NOT_READY:\"Der Spielerpass ist noch nicht öffentlich verfügbar.\",\nINVALID_SESSION:\"Du bist nicht angemeldet oder deine Sitzung ist abgelaufen.\",\nINVALID_VERIFICATION:\"Dieser Bestätigungslink ist ungültig, abgelaufen oder bereits verwendet.\",\nINVALID_LOGIN_LINK:\"Dieser Zugangslink ist ungültig, abgelaufen oder bereits verwendet.\",\nEVENT_NOT_AVAILABLE:\"Die Bestätigung ist momentan nicht verfügbar.\",\nDOCUMENTS_CHANGED:\"Die Teilnahmeunterlagen wurden geändert. Bitte warte auf die aktualisierte Anmeldung.\",\nINVALID_PARTICIPATION:\"Bitte bestätige deine Auswahl erneut.\",\nEVENT_SCHEDULE_CHANGED:\"Der Termin wurde geändert. Lade deinen Spielerpass erneut und prüfe die neuen Zeiten.\",\nEVENT_FULL:\"Alle Plätze für diesen Termin sind aktuell vergeben.\",\nPLAYER_NOT_READY:\"Bitte schliesse zuerst deine Anmeldung und gegebenenfalls die Elternfreigabe ab.\",\nREQUEST_NOT_ALLOWED:\"Diese Anfrage konnte nicht bestätigt werden.\",\nHUNT_TEMPORARILY_UNAVAILABLE:\"Der Spielerpass ist vorübergehend nicht erreichbar. Bitte versuche es später.\"\n};\n\nasync function request(path,body){\n  var options={credentials:\"same-origin\",cache:\"no-store\",signal:AbortSignal.timeout(15000)};\n  if(body!==undefined){\n    options.method=\"POST\";\n    options.headers={\"Content-Type\":\"application/json\",\"X-ALO-Hunt\":\"1\"};\n    options.body=JSON.stringify(body);\n  }\n  var response=await fetch(api+path,options);\n  var data=await response.json();\n  if(!response.ok||data.ok!==true) throw new Error(errors[data.code]||\"Die Anfrage konnte nicht abgeschlossen werden.\");\n  return data;\n}\n\n\nvar missionPanel=document.getElementById(\"mission\");\nvar missionStatus=document.getElementById(\"mission-status\");\nvar missionData=null;\nvar missionBusy=false;\nvar pendingScan=null;\nvar missionKey=\"main\";\nvar scanKey=/^[A-Za-z0-9_-]{1,60}$/;\nif(kind===\"station\"){\n  var scanQuest=fragment.get(\"quest\");\n  var scanStation=fragment.get(\"station\");\n  if(scanKey.test(scanQuest||\"\")&&scanKey.test(scanStation||\"\")&&\n     /^[A-Za-z0-9_-]{43}$/.test(code||\"\")){\n    pendingScan={quest:scanQuest,station:scanStation,code:code};\n    missionKey=scanQuest;\n  }\n  history.replaceState(null,\"\",location.pathname+location.search+\"#mission\");\n  code=null;\n}\n\nfunction resetMission(){\n  renderHuntMap(null);\n  missionData=null;\n  missionPanel.hidden=true;\n  document.getElementById(\"mission-station\").hidden=true;\n  document.getElementById(\"mission-final\").hidden=true;\n}\n\nfunction missionAllowed(){\n  return currentPass&&currentPass.gameAccessAvailable===true;\n}\n\nfunction missionBusyState(value){\n  missionBusy=value;\n  [\"mission-refresh\",\"mission-discover\",\"mission-submit\"].forEach(function(id){\n    document.getElementById(id).disabled=value;\n  });\n}\n\n\nvar huntMapState=null;\nvar huntMapGeneration=0;\n\nfunction huntMapPoint(latitude,longitude,zoom){\n  var size=256*Math.pow(2,zoom);\n  var lat=Math.max(-85.05112878,Math.min(85.05112878,latitude));\n  var sin=Math.sin(lat*Math.PI/180);\n  return {\n    x:(longitude+180)/360*size,\n    y:(0.5-Math.log((1+sin)/(1-sin))/(4*Math.PI))*size\n  };\n}\n\nfunction huntSvg(tag,attributes){\n  var element=document.createElementNS(\"http://www.w3.org/2000/svg\",tag);\n  Object.keys(attributes).forEach(function(key){\n    element.setAttribute(key,String(attributes[key]));\n  });\n  return element;\n}\n\nfunction renderHuntMap(area){\n  var panel=document.getElementById(\"mission-map-panel\");\n  panel.hidden=!area;\n  if(!area){\n    huntMapState=null;\n    huntMapGeneration++;\n    document.getElementById(\"mission-map\").replaceChildren();\n    return;\n  }\n  var key=[area.latitude,area.longitude,area.radiusMeters].join(\":\");\n  if(huntMapState&&huntMapState.key===key) return;\n\n  var svg=document.getElementById(\"mission-map\");\n  var mapStatus=document.getElementById(\"mission-map-status\");\n  var generation=++huntMapGeneration;\n  svg.replaceChildren();\n  mapStatus.textContent=\"Karte wird geladen …\";\n  var cosine=Math.cos(area.latitude*Math.PI/180);\n  var zoom=Math.max(3,Math.min(19,Math.floor(\n    Math.log2(cosine*40075016.686*110/(256*area.radiusMeters))\n  )));\n  var center=huntMapPoint(area.latitude,area.longitude,zoom);\n  var left=center.x-256;\n  var top=center.y-160;\n  var metersPerPixel=cosine*40075016.686/(256*Math.pow(2,zoom));\n  huntMapState={key:key,zoom:zoom,left:left,top:top,\n    metersPerPixel:metersPerPixel,generation:generation};\n\n  var loaded=0,failed=0,total=0;\n  function updateMapStatus(){\n    if(generation!==huntMapGeneration) return;\n    if(loaded+failed<total) return;\n    mapStatus.textContent=failed?\n      \"Ein Teil der Karte konnte nicht geladen werden. Suchradius und Mittelpunkt stehen darunter.\":\n      \"Suche innerhalb des blauen Kreises.\";\n  }\n\n  for(var x=Math.floor(left/256);x<=Math.floor((left+511)/256);x++){\n    for(var y=Math.floor(top/256);y<=Math.floor((top+319)/256);y++){\n      var max=Math.pow(2,zoom);\n      if(y<0||y>=max) continue;\n      total++;\n      var wrappedX=((x%max)+max)%max;\n      var tile=huntSvg(\"image\",{\n        x:x*256-left,y:y*256-top,width:256,height:256,\n        href:\"https://tile.openstreetmap.org/\"+zoom+\"/\"+wrappedX+\"/\"+y+\".png\"\n      });\n      tile.addEventListener(\"load\",function(){loaded++;updateMapStatus();});\n      tile.addEventListener(\"error\",function(){failed++;updateMapStatus();});\n      svg.appendChild(tile);\n    }\n  }\n  svg.appendChild(huntSvg(\"circle\",{\n    cx:256,cy:160,r:area.radiusMeters/metersPerPixel,\n    fill:\"#159cff\", \"fill-opacity\":0.18,\n    stroke:\"#087be0\",\"stroke-width\":3\n  }));\n  var positionLayer=huntSvg(\"g\",{id:\"hunt-map-position\"});\n  svg.appendChild(positionLayer);\n}\n\ndocument.getElementById(\"mission-location\").addEventListener(\"click\",function(){\n  var button=this;\n  var mapStatus=document.getElementById(\"mission-map-status\");\n  if(!huntMapState) return;\n  if(!navigator.geolocation){\n    mapStatus.textContent=\"Standortanzeige ist auf diesem Gerät nicht verfügbar. Du kannst trotzdem spielen.\";\n    return;\n  }\n  var generation=huntMapGeneration;\n  button.disabled=true;\n  mapStatus.textContent=\"Dein Standort wird gesucht …\";\n  navigator.geolocation.getCurrentPosition(function(position){\n    button.disabled=false;\n    if(!huntMapState||generation!==huntMapGeneration) return;\n    var state=huntMapState;\n    var point=huntMapPoint(position.coords.latitude,\n      position.coords.longitude,state.zoom);\n    var x=point.x-state.left,y=point.y-state.top;\n    var layer=document.getElementById(\"hunt-map-position\");\n    layer.replaceChildren();\n    if(x<0||x>512||y<0||y>320){\n      mapStatus.textContent=\"Dein Standort liegt ausserhalb dieses Kartenausschnitts. Gehe zunächst zum Suchgebiet.\";\n      return;\n    }\n    layer.appendChild(huntSvg(\"circle\",{\n      cx:x,cy:y,r:Math.min(500,position.coords.accuracy/state.metersPerPixel),\n      fill:\"#123a80\",\"fill-opacity\":0.12\n    }));\n    layer.appendChild(huntSvg(\"circle\",{\n      cx:x,cy:y,r:7,fill:\"#123a80\",stroke:\"#ffffff\",\"stroke-width\":3\n    }));\n    mapStatus.textContent=\"Der dunkle Punkt ist dein Standort. GPS-Genauigkeit: ungefähr \"+\n      Math.ceil(position.coords.accuracy)+\" Meter.\";\n  },function(){\n    button.disabled=false;\n    if(generation!==huntMapGeneration) return;\n    mapStatus.textContent=\"Standort nicht verfügbar oder nicht freigegeben. Die Karte und das Spiel funktionieren auch ohne.\";\n  },{enableHighAccuracy:true,timeout:12000,maximumAge:15000});\n});\n\n\nfunction renderMission(data){\n  document.getElementById(\"mission-title\").textContent=data.quest.title;\n  document.getElementById(\"mission-introduction\").textContent=data.quest.introduction;\n  document.getElementById(\"mission-progress-label\").textContent=\n    data.progress.completed+\" von \"+data.progress.total+\" Stationen gelöst\";\n  var bar=document.getElementById(\"mission-progress\");\n  bar.max=data.progress.total||1;\n  bar.value=data.progress.completed;\n  var digits=document.getElementById(\"mission-digits\");\n  digits.replaceChildren();\n  var earned=new Map(data.progress.digits.map(function(item){\n    return [item.position,item.digit];\n  }));\n  for(var position=1;position<=data.progress.total;position++){\n    var tile=document.createElement(\"span\");\n    tile.className=\"digit-tile\"+(earned.has(position)?\" earned\":\"\");\n    tile.textContent=earned.has(position)?earned.get(position):\"–\";\n    tile.setAttribute(\"aria-label\",\"Ziffer \"+position+\": \"+\n      (earned.has(position)?earned.get(position):\"noch nicht gefunden\"));\n    digits.appendChild(tile);\n  }\n\n  var station=data.currentStation;\n  document.getElementById(\"mission-station\").hidden=!station;\n  document.getElementById(\"mission-final\").hidden=data.finalUnlocked!==true;\n  if(!station){renderHuntMap(null);return;}\n  renderHuntMap(station.searchArea);\n\n  document.getElementById(\"mission-position\").textContent=\n    \"CHECKPOINT \"+station.position+\" / \"+data.progress.total;\n  document.getElementById(\"mission-station-title\").textContent=station.title;\n  document.getElementById(\"mission-task\").textContent=station.task;\n  var area=document.getElementById(\"mission-area\");\n  area.hidden=!station.searchArea;\n  area.textContent=station.searchArea?\n    \"Dein Suchbereich: \"+station.searchArea.radiusMeters+\n    \" Meter Radius um \"+\n    station.searchArea.latitude.toFixed(5)+\", \"+\n    station.searchArea.longitude.toFixed(5)+\".\":\"\";\n\n  var observation=station.accessMode===\"OBSERVATION\";\n  document.getElementById(\"mission-discovery\").textContent=observation?\n    \"Schau dich vor Ort um. Die Antwort findest du an dem beschriebenen Ort. Dafür brauchst du keinen QR-Code.\":\n    station.discovered?\n      \"Checkpoint gefunden. Jetzt kannst du die Aufgabe lösen.\":\n      \"Scanne den QR-Code am Checkpoint mit deiner Handykamera.\";\n\n  document.getElementById(\"mission-discover\").hidden=\n    observation||station.discovered||!pendingScan||\n    pendingScan.quest!==missionKey||pendingScan.station!==station.key;\n\n  document.getElementById(\"mission-answer-form\").hidden=\n    station.canAnswer!==true;\n\n  var answerHint=document.getElementById(\"mission-answer-hint\");\n  answerHint.hidden=!station.answerHint;\n  answerHint.textContent=station.answerHint?\n    \"Deine Antwort passt hier hinein: \"+station.answerHint:\"\";\n\n  var nextArea=document.getElementById(\"mission-next-area\");\n  nextArea.hidden=!station.nextSearchAreaAt;\n  nextArea.textContent=station.nextSearchAreaAt?\n    \"Der Suchbereich wird kleiner: \"+\n    formatHuntDate(station.nextSearchAreaAt)+\" Uhr.\":\"\";\n\n  var list=document.getElementById(\"mission-hint-list\");\n  list.replaceChildren();\n  station.hints.forEach(function(hint){\n    var paragraph=document.createElement(\"p\");\n    paragraph.className=\"notice\";\n    paragraph.textContent=hint.text;\n    list.appendChild(paragraph);\n  });\n  document.getElementById(\"mission-hints\").hidden=\n    !station.hints.length&&!station.nextHintAt;\n  document.getElementById(\"mission-next-hint\").textContent=\n    station.nextHintAt?\"Nächster Tipp: \"+formatHuntDate(station.nextHintAt)+\" Uhr\":\"\";\n}\n\nasync function loadMission(){\n  if(!missionAllowed()){resetMission();return false;}\n  var playerId=currentPass.player.id;\n  missionPanel.hidden=false;\n  missionStatus.textContent=\"Deine Mission wird geladen …\";\n  missionData=null;\n  document.getElementById(\"mission-station\").hidden=true;\n  document.getElementById(\"mission-final\").hidden=true;\n  try{\n    var data=await request(\"/quests/\"+encodeURIComponent(missionKey));\n    if(!missionAllowed()||currentPass.player.id!==playerId) return false;\n    if(data.available!==true){\n      missionStatus.textContent=data.message||\"Das Spiel ist momentan nicht geöffnet.\";\n      return false;\n    }\n    missionData=data;\n    renderMission(data);\n    missionStatus.textContent=\"\";\n    if(pendingScan&&data.currentStation&&\n       pendingScan.station!==data.currentStation.key){\n      missionStatus.textContent=\"Dieser QR gehört nicht zur aktuellen Station. Dein Fortschritt bleibt unverändert.\";\n    }\n    return true;\n  }catch(error){\n    if(missionAllowed()&&currentPass.player.id===playerId){\n      missionStatus.textContent=error instanceof Error?error.message:\n        \"Mission momentan nicht erreichbar.\";\n    }\n    return false;\n  }\n}\n\ndocument.getElementById(\"mission-refresh\").addEventListener(\"click\",async function(){\n  if(missionBusy||attendanceBusy) return;\n  missionBusyState(true);\n  try{await loadMission();}finally{missionBusyState(false);}\n});\n\ndocument.getElementById(\"mission-discover\").addEventListener(\"click\",async function(){\n  if(missionBusy||attendanceBusy||!missionAllowed()||\n     !pendingScan||!missionData||!missionData.currentStation) return;\n  var station=missionData.currentStation;\n  if(pendingScan.quest!==missionKey||pendingScan.station!==station.key) return;\n  missionBusyState(true);\n  try{\n    await request(\"/quests/\"+encodeURIComponent(missionKey)+\n      \"/stations/\"+encodeURIComponent(station.key)+\"/action\",\n      {type:\"DISCOVER\",code:pendingScan.code});\n    pendingScan=null;\n    if(await loadMission()) missionStatus.textContent=\"Checkpoint entdeckt!\";\n  }catch(error){\n    missionStatus.textContent=error instanceof Error?error.message:\"Fund konnte nicht bestätigt werden.\";\n  }finally{missionBusyState(false);}\n});\n\ndocument.getElementById(\"mission-answer-form\").addEventListener(\"submit\",async function(event){\n  event.preventDefault();\n  if(missionBusy||attendanceBusy||!missionAllowed()||\n     !missionData||!missionData.currentStation) return;\n  var station=missionData.currentStation;\n  if(station.canAnswer!==true) return;\n  var answer=document.getElementById(\"mission-answer\");\n  missionBusyState(true);\n  try{\n    var result=await request(\"/quests/\"+encodeURIComponent(missionKey)+\n      \"/stations/\"+encodeURIComponent(station.key)+\"/action\",\n      {type:\"SOLVE\",answer:answer.value});\n    if(result.limited){\n      missionStatus.textContent=\"Kurze Denkpause: Bitte in \"+\n        result.retryAfterSeconds+\" Sekunden erneut versuchen.\";\n    }else if(!result.correct){\n      missionStatus.textContent=\"Noch nicht richtig. Schau dir die Aufgabe und Tipps nochmals an.\";\n    }else{\n      answer.value=\"\";\n      if(await loadMission()){\n        missionStatus.textContent=\"Richtig! Ziffer \"+result.earnedDigit+\" gesammelt.\";\n      }\n    }\n  }catch(error){\n    missionStatus.textContent=error instanceof Error?error.message:\n      \"Antwort konnte nicht geprüft werden.\";\n  }finally{missionBusyState(false);}\n});\n\nasync function loadPass(){\n  currentPass=null;\n  withdrawalPanel.hidden=true;\n  try{\n    var data=await request(\"/pass\");\n    document.getElementById(\"pass-alias\").textContent=data.player.alias;\n    document.getElementById(\"pass-message\").textContent=data.message;\n    var phases={WAITLIST:\"Termin folgt\",UPCOMING:\"Termin angekündigt\",LIVE:\"Event läuft\",PAUSED:\"Pausiert\",FINISHED:\"Beendet\",CANCELLED:\"Abgesagt\"};\n    document.getElementById(\"pass-phase\").textContent=phases[data.event.phase]||\"In Vorbereitung\";\n    document.getElementById(\"pass-guardian\").textContent=!data.player.guardianRequired?\"Nicht erforderlich\":data.player.guardianApproved?\"Bestätigt\":\"Ausstehend\";\n    document.getElementById(\"pass-docs\").textContent=data.player.documentsCurrent?\"Aktuell\":\"Aktualisierung erforderlich\";\n    currentPass=data;\n    renderAttendance(data);\n    document.getElementById(\"pass-content\").hidden=false;\n    document.getElementById(\"pass-intro\").hidden=true;\n    status.textContent=\"\";\n    if(data.gameAccessAvailable===true){\n      missionBusyState(true);\n      try{await loadMission();}finally{missionBusyState(false);}\n    }else{resetMission();}\n    return true;\n  }catch(error){\n    document.getElementById(\"pass-content\").hidden=true;\n    resetMission();\n    status.textContent=error instanceof Error?error.message:\"Verbindungsproblem. Bitte später erneut versuchen.\";\n    return false;\n  }\n}\n\nbutton.addEventListener(\"click\",async function(){\n  if(!linkReady) return;\n  button.disabled=true;\n  status.textContent=\"Dein Link wird geprüft …\";\n  try{\n    await request(kind===\"verify\"?\"/verify-contact\":\"/login/consume\",{code:code});\n    code=null;linkReady=false;\n    document.getElementById(\"link-panel\").hidden=true;\n    await loadPass();\n  }catch(error){\n    status.textContent=error instanceof Error?error.message:\"Verbindungsproblem. Bitte erneut versuchen.\";\n  }finally{button.disabled=false;}\n});\n\nconfirmAttendance.addEventListener(\"click\",async function(){\n  if(attendanceBusy||!currentPass||\n     currentPass.participation.canConfirm!==true) return;\n  var event=currentPass.event;\n  setAttendanceBusy(true);\n  status.textContent=\"Dein Platz wird bestätigt …\";\n  try{\n    await request(\"/participation/confirm\",{\n      confirmAttendance:true,\n      startsAt:event.startsAt,\n      endsAt:event.endsAt,\n      rulesVersion:event.rulesVersion,\n      privacyVersion:event.privacyVersion\n    });\n    if(await loadPass()){\n      status.textContent=\"Du bist dabei. Dein Platz ist bestätigt.\";\n    }\n  }catch(error){\n    var message=error instanceof Error?error.message:\"Bestätigung momentan nicht möglich.\";\n    if(await loadPass()) status.textContent=message;\n  }finally{setAttendanceBusy(false);}\n});\n\nshowWithdrawal.addEventListener(\"click\",function(){\n  if(attendanceBusy||!currentPass||\n     currentPass.participation.canWithdraw!==true) return;\n  withdrawalPanel.hidden=false;\n  cancelWithdrawal.focus();\n});\n\ncancelWithdrawal.addEventListener(\"click\",function(){\n  if(attendanceBusy) return;\n  withdrawalPanel.hidden=true;\n  showWithdrawal.focus();\n});\n\nconfirmWithdrawal.addEventListener(\"click\",async function(){\n  if(attendanceBusy||withdrawalPanel.hidden||!currentPass||\n     currentPass.participation.canWithdraw!==true) return;\n  setAttendanceBusy(true);\n  status.textContent=\"Deine Teilnahme wird abgesagt …\";\n  try{\n    await request(\"/participation/withdraw\",{confirmWithdrawal:true});\n    if(await loadPass()){\n      status.textContent=\"Deine Teilnahme wurde abgesagt. Dein Platz ist freigegeben.\";\n      document.getElementById(\"logout\").focus();\n    }\n  }catch(error){\n    status.textContent=error instanceof Error?error.message:\"Absage momentan nicht möglich.\";\n  }finally{setAttendanceBusy(false);}\n});\n\ndocument.getElementById(\"logout\").addEventListener(\"click\",async function(){\n  if(attendanceBusy) return;\n  var logoutButton=this;\n  logoutButton.disabled=true;\n  setAttendanceBusy(true);\n  try{\n    await request(\"/logout\",{});\n    document.getElementById(\"pass-content\").hidden=true;\n    document.getElementById(\"pass-intro\").hidden=false;\n    currentPass=null;\n    pendingScan=null;\n    resetMission();\n    withdrawalPanel.hidden=true;\n    status.textContent=\"Du bist ausgeloggt. Dein Spielerpass und deine Teilnahme bleiben gespeichert.\";\n  }catch(error){\n    status.textContent=error instanceof Error?error.message:\"Abmelden momentan nicht möglich.\";\n  }finally{logoutButton.disabled=false;setAttendanceBusy(false);}\n});\n\ndocument.getElementById(\"registration-form\").addEventListener(\"submit\",function(event){event.preventDefault();});\nif(!linkReady) loadPass();\n})();\n</script>\n</body>\n</html>";

export function renderHuntPage(nonce: string): string {
  if (!/^[A-Za-z0-9_-]+$/.test(nonce)) throw new Error("INVALID_NONCE");
  return huntPageHtml.replaceAll("__HUNT_NONCE__", nonce);
}
